operation.add:
{% if ukrposhta_order %}
<div id="ukrposhta-order-inject">{{ ukrposhta_order }}</div>
<script>
$(function () {
  var $box = $('#ukrposhta-order-inject');
  var $panel = $box.find('#ukrposhta-order-panel');
  if ($panel.length && $('#content .container-fluid').children('.panel').first().length) {
    $('#content .container-fluid').children('.panel').first().after($panel);
  }
  $box.remove();
});
</script>
{% endif %}

if ($this->user->hasPermission('access', 'extension/shipping/ukrposhta')) {
	$up_name = 'Укрпошта';
	$up_settings = 'Налаштування';
	$up_cn = 'Накладні';
	if (strpos((string)$this->config->get('config_admin_language'), 'ru') === 0) {
		$up_name = 'Укрпочта';
		$up_settings = 'Настройки';
		$up_cn = 'Накладные';
	}
	$up_token = isset($this->session->data['user_token']) ? 'user_token=' . $this->session->data['user_token'] : 'token=' . (isset($this->session->data['token']) ? $this->session->data['token'] : '');
	$data['menus'][] = array(
		'id' => 'menu-ukrposhta',
		'icon' => 'fa-truck',
		'name' => $up_name,
		'href' => '',
		'children' => array(
			array(
				'name' => $up_settings,
				'href' => $this->url->link('extension/shipping/ukrposhta', $up_token, true),
				'children' => array()
			),
			array(
				'name' => $up_cn,
				'href' => $this->url->link('extension/shipping/ukrposhta/shipments', $up_token, true),
				'children' => array()
			)
		)
	);
}
